<?php
function chat_access(array $u,array $h): bool { return $u['quyen']==='ADMIN'||(int)$h['khach_hang_id']===(int)$u['id']||(int)$h['nhan_vien_id']===(int)$u['id']; }
function conversation(int $id,array $u,bool $lock=false): array { $h=db_one('SELECT * FROM hoi_thoai_chat WHERE ma_hoi_thoai=?'.($lock?' FOR UPDATE':''),[$id]);must($h&&chat_access($u,$h),'Hội thoại không nằm trong phạm vi truy cập.',404);return $h; }
function create_chat(array $u,string $config,string $body): int { must($u['quyen']==='KHACH_HANG','Chỉ khách hàng tạo yêu cầu.',403);valid_text($body,4000);if($config)must(db_one('SELECT 1 FROM cau_hinh_xe WHERE ma_cau_hinh=? AND hien_thi=1',[$config]),'Cấu hình không hợp lệ.');return transaction(function()use($u,$config,$body){$s=db_one("SELECT n.* FROM nhan_vien_truc n JOIN tai_khoan t ON t.id=n.nhan_vien_id WHERE n.online_luc>DATE_SUB(NOW(),INTERVAL 90 SECOND) AND t.quyen='NHAN_VIEN' AND t.trang_thai='HOAT_DONG' ORDER BY n.nhan_gan_nhat,n.nhan_vien_id LIMIT 1 FOR UPDATE");execute('INSERT INTO hoi_thoai_chat(khach_hang_id,nhan_vien_id,ma_cau_hinh,trang_thai)VALUES(?,?,?,?)',[$u['id'],$s['nhan_vien_id']??null,$config?:null,$s?'DANG_TU_VAN':'CHO_TIEP_NHAN']);$id=insert_id();execute('INSERT INTO tin_nhan(ma_hoi_thoai,nguoi_gui_id,noi_dung)VALUES(?,?,?)',[$id,$u['id'],$body]);if($s){execute('UPDATE nhan_vien_truc SET nhan_gan_nhat=NOW() WHERE nhan_vien_id=?',[$s['nhan_vien_id']]);execute('INSERT IGNORE INTO phan_cong_khach(khach_hang_id,nhan_vien_id)VALUES(?,?)',[$u['id'],$s['nhan_vien_id']]);}return $id;}); }
function claim_chat(array $u,int $id): void { must($u['quyen']==='NHAN_VIEN','Nhân viên bán hàng mới nhận tư vấn.',403);transaction(function()use($u,$id){$h=db_one('SELECT * FROM hoi_thoai_chat WHERE ma_hoi_thoai=? FOR UPDATE',[$id]);must($h&&$h['nhan_vien_id']===null&&$h['trang_thai']==='CHO_TIEP_NHAN','Hội thoại đã được tiếp nhận.');execute("UPDATE hoi_thoai_chat SET nhan_vien_id=?,trang_thai='DANG_TU_VAN' WHERE ma_hoi_thoai=?",[$u['id'],$id]);execute('INSERT IGNORE INTO phan_cong_khach(khach_hang_id,nhan_vien_id)VALUES(?,?)',[$h['khach_hang_id'],$u['id']]);audit('NHAN_TU_VAN','hoi_thoai_chat',(string)$id);}); }
function send_chat(array $u,int $id,string $body,?array $file=null): int { require_once __DIR__.'/catalog.php';valid_text($body,4000,false);must($body!==''||($file&&($file['error']??UPLOAD_ERR_NO_FILE)!==UPLOAD_ERR_NO_FILE),'Nhập tin nhắn hoặc chọn tệp đính kèm.');$saved=null;conversation($id,$u);if($file&&($file['error']??UPLOAD_ERR_NO_FILE)!==UPLOAD_ERR_NO_FILE)$saved=upload_file($file,true,true);try{return transaction(function()use($u,$id,$body,$saved){$h=conversation($id,$u,true);must($h['trang_thai']!=='DA_KET_THUC','Hội thoại đã kết thúc.');execute('INSERT INTO tin_nhan(ma_hoi_thoai,nguoi_gui_id,noi_dung)VALUES(?,?,?)',[$id,$u['id'],$body]);$msg=insert_id();if($saved)execute('INSERT INTO tep_tin_nhan(ma_tin_nhan,duong_dan,ten_goc,mime)VALUES(?,?,?,?)',[$msg,$saved['path'],$saved['name'],$saved['mime']]);return $msg;});}catch(Throwable $e){if($saved)unlink(PRIVATE_DIR.'/'.$saved['path']);throw $e;} }
